"use server";

import { prisma } from "@/lib/db";
import { revalidatePath } from "next/cache";
import { getSession } from "@/lib/auth";
import { assertCharityAccess } from "@/lib/access";
import { requirePermission } from "@/lib/guards";
import { syncServiceProgress } from "./services";

async function getGovernanceService(charityId: string) {
  let service = await prisma.service.findFirst({
    where: { charityId, department: "GOVERNANCE" }
  });
  if (!service) {
    const charity = await prisma.charity.findUnique({ where: { id: charityId } });
    const timelineName = charity?.governanceTimelineName || "الحوكمة";
    service = await prisma.service.create({
      data: {
        name: timelineName,
        department: "GOVERNANCE",
        charityId,
        responsibleName: charity?.governanceResponsibleName,
        responsiblePhone: charity?.governanceResponsiblePhone
      }
    });
  }
  return service;
}

export async function addGovernanceStage(
  charityId: string,
  name: string,
  duration?: string,
  description?: string,
  startDate?: string,
  endDate?: string,
  isContinuous: boolean = false,
  isActive: boolean = true
) {
  const session = await getSession();
  if (!session) throw new Error("UNAUTHORIZED");
  await assertCharityAccess(session.id, session.role, charityId);
  const service = await getGovernanceService(charityId);
  const lastStage = await prisma.serviceStage.findFirst({
    where: { serviceId: service.id },
    orderBy: { order: 'desc' }
  });

  const newOrder = lastStage ? lastStage.order + 1 : 0;

  await prisma.serviceStage.create({
    data: {
      name,
      duration,
      description: description || null,
      startDate: startDate ? new Date(startDate) : null,
      endDate: endDate ? new Date(endDate) : null,
      order: newOrder,
      serviceId: service.id,
      isCurrent: false,
      isContinuous,
      isActive
    }
  });

  const charity = await prisma.charity.findUnique({ where: { id: charityId } });
  if (charity) {
    revalidatePath(`/portal/${encodeURIComponent(charity.name)}`);
    revalidatePath(`/portal/${encodeURIComponent(charity.name)}/governance`);
  }
}

export async function updateGovernanceStage(
  stageId: string,
  name: string,
  duration?: string,
  description?: string,
  startDate?: string,
  endDate?: string,
  isContinuous: boolean = false,
  isActive: boolean = true,
  isComingSoon: boolean = false
) {
  const session = await getSession();
  if (!session) throw new Error("UNAUTHORIZED");
  const stageRef = await prisma.serviceStage.findUnique({ where: { id: stageId }, include: { service: { include: { charity: true } } } });
  if (stageRef) await assertCharityAccess(session.id, session.role, stageRef.service.charityId);
  const stage = await prisma.serviceStage.update({
    where: { id: stageId },
    data: {
      name,
      duration,
      description: description || null,
      startDate: startDate ? new Date(startDate) : null,
      endDate: endDate ? new Date(endDate) : null,
      isContinuous,
      isActive,
      isComingSoon
    },
    include: { service: { include: { charity: true } } }
  });

  revalidatePath(`/portal/${encodeURIComponent(stage.service.charity.name)}`);
  revalidatePath(`/portal/${encodeURIComponent(stage.service.charity.name)}/governance`);
}

export async function deleteGovernanceStage(stageId: string) {
  const session = await getSession();
  if (!session) throw new Error("UNAUTHORIZED");
  const stageRef = await prisma.serviceStage.findUnique({ where: { id: stageId }, include: { service: { include: { charity: true } } } });
  if (stageRef) await assertCharityAccess(session.id, session.role, stageRef.service.charityId);
  const stage = await prisma.serviceStage.delete({
    where: { id: stageId },
    include: { service: { include: { charity: true } } }
  });

  revalidatePath(`/portal/${encodeURIComponent(stage.service.charity.name)}`);
  revalidatePath(`/portal/${encodeURIComponent(stage.service.charity.name)}/governance`);
}

export async function toggleActiveGovernanceStage(stageId: string, isActive: boolean) {
  // Same guard as its siblings above — was previously reachable with no session.
  const session = await getSession();
  if (!session) throw new Error("UNAUTHORIZED");
  const stageRef = await prisma.serviceStage.findUnique({ where: { id: stageId }, include: { service: true } });
  if (stageRef) await assertCharityAccess(session.id, session.role, stageRef.service.charityId);

  const stage = await prisma.serviceStage.update({
    where: { id: stageId },
    data: { isActive },
    include: { service: { include: { charity: true } } }
  });

  revalidatePath(`/portal/${encodeURIComponent(stage.service.charity.name)}`);
  revalidatePath(`/portal/${encodeURIComponent(stage.service.charity.name)}/governance`);
}

export async function setCurrentGovernanceStage(charityId: string, stageId: string) {
  const session = await getSession();
  if (!session) throw new Error("UNAUTHORIZED");
  await assertCharityAccess(session.id, session.role, charityId);
  
  const service = await getGovernanceService(charityId);
  await syncServiceProgress(service.id, stageId);

  const updatedStage = await prisma.serviceStage.findUnique({
    where: { id: stageId },
    include: { service: { include: { charity: true } } }
  });

  if (updatedStage) {
    revalidatePath(`/portal/${encodeURIComponent(updatedStage.service.charity.name)}`);
    revalidatePath(`/portal/${encodeURIComponent(updatedStage.service.charity.name)}/governance`);
  }
}

export async function toggleCurrentGovernanceStage(stageId: string, isCurrent: boolean) {
  const session = await getSession();
  if (!session) throw new Error("UNAUTHORIZED");
  const stage = await prisma.serviceStage.update({
    where: { id: stageId },
    data: { isCurrent },
    include: { service: { include: { charity: true } } }
  });
  revalidatePath(`/portal/${encodeURIComponent(stage.service.charity.name)}/governance`);
}

export async function reorderGovernanceStages(charityId: string, stageIds: string[]) {
  const session = await getSession();
  if (!session) throw new Error("UNAUTHORIZED");
  await assertCharityAccess(session.id, session.role, charityId);
  for (let i = 0; i < stageIds.length; i++) {
    await prisma.serviceStage.update({
      where: { id: stageIds[i] },
      data: { order: i }
    });
  }

  const charity = await prisma.charity.findUnique({ where: { id: charityId } });
  if (charity) {
    revalidatePath(`/portal/${encodeURIComponent(charity.name)}`);
    revalidatePath(`/portal/${encodeURIComponent(charity.name)}/governance`);
  }
}

// Regulations are global (not charity-scoped), so there is no charity to check
// access against — these gate on the governance permission instead.
export async function addRegulation(title: string, category: string, link: string, description?: string) {
  await requirePermission("manage_governance");

  await prisma.regulation.create({
    data: {
      title,
      description,
      category,
      link,
    }
  });

  revalidatePath("/", "layout");
}

export async function deleteRegulation(regulationId: string) {
  await requirePermission("manage_governance");

  await prisma.regulation.delete({
    where: { id: regulationId },
  });

  revalidatePath("/", "layout");
}

export async function toggleRegulationVisibility(charityId: string, regulationId: string, isCurrentlyVisible: boolean) {
  const session = await getSession();
  if (!session) throw new Error("UNAUTHORIZED");
  await assertCharityAccess(session.id, session.role, charityId);

  if (isCurrentlyVisible) {
    await prisma.charityRegulationVisibility.create({
      data: {
        charityId,
        regulationId,
        isVisible: false
      }
    });
  } else {
    await prisma.charityRegulationVisibility.deleteMany({
      where: {
        charityId,
        regulationId,
      }
    });
  }

  revalidatePath("/", "layout");
}

export async function updateCharitySize(charityId: string, size: "MICRO" | "SMALL" | "MEDIUM" | "LARGE" | "MEGA") {
  try {
    const session = await getSession();
    if (!session) return { success: false, error: "غير مصرح" };
    await assertCharityAccess(session.id, session.role, charityId);

    await prisma.charity.update({
      where: { id: charityId },
      data: { size },
    });
    revalidatePath(`/portal/[name]/governance`);
    return { success: true };
  } catch (error) {
    console.error("Failed to update charity size:", error);
    return { success: false, error: "حدث خطأ أثناء تحديث حجم الجمعية" };
  }
}

export async function updateCharityRevenueAndSize(charityId: string, revenue: number) {
  try {
    const session = await getSession();
    if (!session) return { success: false, error: "غير مصرح" };
    await assertCharityAccess(session.id, session.role, charityId);

    let size: "MICRO" | "SMALL" | "MEDIUM" | "LARGE" | "MEGA" = "MEGA";
    if (revenue <= 500000) size = "MICRO";
    else if (revenue <= 2000000) size = "SMALL";
    else if (revenue <= 8000000) size = "MEDIUM";
    else if (revenue <= 30000000) size = "LARGE";

    await prisma.charity.update({
      where: { id: charityId },
      data: { annualRevenue: revenue, size },
    });
    revalidatePath(`/portal/[name]/governance`);
    return { success: true, size, revenue };
  } catch (error) {
    console.error("Failed to update charity revenue:", error);
    return { success: false, error: "حدث خطأ أثناء تحديث الإيرادات" };
  }
}

export async function updateGovernanceProgress(
  charityId: string,
  indicatorId: string,
  status: string,
  proofUrl?: string,
  proofPublicId?: string
) {
  try {
    const session = await getSession();
    if (!session) return { success: false, error: "غير مصرح" };
    await assertCharityAccess(session.id, session.role, charityId);

    await prisma.governanceProgress.upsert({
      where: {
        charityId_indicatorId: {
          charityId,
          indicatorId,
        },
      },
      update: {
        status,
        ...(proofUrl && { proofUrl }),
        ...(proofPublicId && { proofPublicId }),
      },
      create: {
        charityId,
        indicatorId,
        status,
        proofUrl,
        proofPublicId,
      },
    });
    revalidatePath(`/portal/[name]/governance`);
    return { success: true };
  } catch (error) {
    console.error("Failed to update governance progress:", error);
    return { success: false, error: "حدث خطأ أثناء تحديث الإنجاز" };
  }
}
